'use strict';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'Rs. '+Number(n).toLocaleString('en-PK');
const date=s=>new Date(s.includes('T')?s:s+'Z').toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const route='/'+(new URLSearchParams(location.search).get('page')||'');
const demoURL=p=>'./index.html'+(p==='/'?'':'?page='+p.replace(/^\//,''));
let state={products:[],categories:[],settings:{},user:null},cart=[],wishlist=[],filter=new URLSearchParams(location.search).get('category')||'All',search='',sort='featured',toastTimer,selectedProduct=null,quantity=1,galleryIndex=0,selectedShade='',selectedSize='',signup=false,adminTab=location.hash.slice(1)||'overview',overview=null,adminSearch='',editingProduct=null,editImages=[],activeConversation=null,customerConversation=null,chatOpened=false,messageFingerprint='',customerFingerprint='',pendingSave=Promise.resolve(),chatBusy=false;
const readLocal=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}};
function writeLocal(key,value){try{localStorage.setItem(key,JSON.stringify(value))}catch{}}
async function api(path,method='GET',data){return window.demoAPI(path,method,data)}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
const wa=text=>'https://wa.me/'+state.settings.whatsapp+(text?'?text='+encodeURIComponent(text):'');
const findProduct=id=>state.products.find(p=>p.id===Number(id));
const itemKey=item=>[item.productId,item.shade||'',item.size||''].join('|');
function normalizeCart(items){const used={},result=[];for(const item of items||[]){const p=findProduct(item.productId);if(!p||!p.stock)continue;if((p.shades.length&&!p.shades.includes(item.shade))||(!p.shades.length&&item.shade)||(p.sizes.length&&!p.sizes.includes(item.size))||(!p.sizes.length&&item.size))continue;const q=Math.min(Math.max(0,Math.floor(Number(item.quantity)||0)),p.stock-(used[p.id]||0));if(q<=0)continue;used[p.id]=(used[p.id]||0)+q;const old=result.find(x=>itemKey(x)===itemKey(item));if(old)old.quantity+=q;else result.push({productId:p.id,shade:item.shade||'',size:item.size||'',quantity:q})}return result}
function persist(){cart=normalizeCart(cart);wishlist=wishlist.filter(id=>findProduct(id));if(state.user){const data={cart:structuredClone(cart),wishlist:[...wishlist]};pendingSave=pendingSave.catch(()=>{}).then(()=>api('/preferences','PUT',data)).catch(error=>{toast('Bag changes could not be saved: '+error.message);throw error});pendingSave.catch(()=>{});}else{writeLocal('rb-demo-cart',cart);writeLocal('rb-demo-wishlist',wishlist)}updateCounts()}
function updateCounts(){const count=cart.reduce((s,i)=>s+i.quantity,0);$$('[data-bag-count]').forEach(el=>el.textContent=count);$$('[data-wish-count]').forEach(el=>el.textContent=wishlist.length);$$('[data-wish]').forEach(el=>{const saved=wishlist.includes(Number(el.dataset.wish));el.classList.toggle('saved',saved);el.setAttribute('aria-pressed',String(saved));el.textContent=saved?'♥':'♡'})}
async function bootstrap(){state=await api('/bootstrap');if(state.user){cart=state.preferences.cart;wishlist=state.preferences.wishlist}else{cart=normalizeCart(readLocal('rb-demo-cart',[]));wishlist=readLocal('rb-demo-wishlist',[]).filter(id=>findProduct(id))}render();if(route!=='/admin'&&route!=='/setup')pollCustomer().catch(()=>{});else if(state.user?.role==='admin')await loadOverview()}
async function reloadCatalogue(){const fresh=await api('/bootstrap');state.products=fresh.products;state.categories=fresh.categories;state.settings=fresh.settings;cart=normalizeCart(cart);wishlist=wishlist.filter(id=>findProduct(id));updateCounts()}
function logo(){return '<a class="logo" href="./index.html"><small>THE</small><strong>Royal Blush<span class="star">✧</span></strong></a>'}
function header(){return `<div class="announcement">IMPORTED BEAUTY <span>✧</span> LIMITED BY DESIGN <span>✧</span> KARACHI, PAKISTAN</div><header class="site-header"><nav class="nav wrap" aria-label="Main navigation">${logo()}<div class="navlinks"><a class="${route==='/'?'current':''}" href="./index.html">Home</a><a class="${route==='/shop'?'current':''}" href="./index.html?page=shop">The collection</a><a href="./index.html#story">Our story</a><a href="./index.html?page=info">Customer care</a></div><div class="nav-actions"><a class="icon-btn" href="./index.html?page=shop" aria-label="Search products">⌕</a><a class="icon-btn" href="./index.html?page=account" aria-label="Your account"><svg class="icon" viewBox="0 0 24 24"><circle cx="12" cy="7" r="3.5"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/></svg></a><a class="icon-btn" href="./index.html?page=wishlist" aria-label="Wishlist">♡<small data-wish-count>${wishlist.length}</small></a><button class="icon-btn" data-action="bag" aria-label="Open shopping bag"><svg class="icon" viewBox="0 0 24 24"><path d="M5 8h14l1 13H4L5 8Z M8 9V6a4 4 0 0 1 8 0v3"/></svg><span class="bag-count" data-bag-count>0</span></button><button class="icon-btn menu-toggle" data-action="menu" aria-expanded="false" aria-label="Toggle navigation">☰</button></div></nav><nav class="mobile-nav" id="mobile-nav" aria-label="Mobile navigation" hidden><a href="./index.html">Home</a><a href="./index.html?page=shop">The collection</a><a href="./index.html#story">Our story</a><a href="./index.html?page=info">Customer care</a><a href="./index.html?page=account">My account</a></nav></header>`}
function footer(){return `<section class="promises wrap" aria-label="Our approach"><div class="promise"><span>✧</span><div><h3>Beauty, from abroad.</h3><p>A considered edit of imported beauty finds.</p></div></div><div class="promise"><span>◇</span><div><h3>Limited by design.</h3><p>Small quantities. Something new to discover.</p></div></div><div class="promise"><span>♡</span><div><h3>Here for you.</h3><p>Ask our team in chat or on WhatsApp.</p></div></div></section><footer><div class="footer-main wrap"><div class="footer-brand">${logo()}<p>Imported beauty, limited by design.<br>Curated with care in Karachi, Pakistan.</p></div><div><h3>Explore</h3><a href="./index.html?page=shop">Shop the collection</a><a href="./index.html?page=wishlist">Your wishlist</a><a href="./index.html?page=account">My account</a><a href="./index.html?page=info">Delivery & returns</a></div><div><h3>Let’s talk beauty</h3><a href="${wa()}" target="_blank" rel="noopener">WhatsApp ↗</a><button class="text-link" data-action="chat">Message our team</button><p>Karachi, Pakistan<br>Availability confirmed personally.</p></div></div><div class="footer-bottom wrap"><span>© ${new Date().getFullYear()} The Royal Blush.</span><a class="store-team" href="./index.html?page=admin">Store team</a></div></footer>`}
function floating(){return `<div class="float-actions"><button class="float-btn chat-float" data-action="chat" aria-label="Open customer chat" aria-expanded="false"><svg class="icon" viewBox="0 0 24 24"><path d="M21 11a9 9 0 0 1-9 9H4l-3 2 1-6a9 9 0 1 1 19-5Z"/><path d="M7 11h1m3 0h1m3 0h1"/></svg><span id="chat-unread" class="chat-unread" hidden></span></button><a class="float-btn wa" href="${wa()}" target="_blank" rel="noopener" aria-label="Message on WhatsApp"><svg viewBox="0 0 32 32" fill="currentColor"><path d="M16 3a12.7 12.7 0 0 0-11 19.1L3 29l7.1-1.9A13 13 0 1 0 16 3Zm0 23.5c-2 0-3.9-.5-5.6-1.6l-.4-.2-4.2 1.1 1.1-4.1-.3-.4A10.6 10.6 0 1 1 16 26.5Zm5.8-7.9c-.3-.1-1.8-.9-2.1-1s-.5-.2-.7.2-.8 1-.9 1.2-.3.2-.6.1a8.6 8.6 0 0 1-4.2-3.7c-.3-.5.3-.5.9-1.7.1-.2 0-.4 0-.6l-.9-2.2c-.2-.5-.5-.5-.7-.5H12c-.2 0-.6.1-.8.4-.8.8-1.1 1.6-1.1 2.5 0 1.5 1.1 2.9 1.3 3.1.1.2 2.2 3.4 5.4 4.8 2 .9 2.8.9 3.8.7.6-.1 1.8-.8 2-1.5.3-.7.3-1.4.2-1.5-.1-.1-.3-.2-1-.5Z"/></svg></a></div><aside id="chat-panel" class="chat-panel" aria-label="Royal Blush customer chat" hidden><div class="chat-heading"><div>Royal Blush concierge<small>Demo chat · not connected to the store</small></div><button data-action="close-chat" aria-label="Close chat">×</button></div><div id="chat-inner"></div></aside>`}
function stockLabel(p){return p.stock===0?'Sold out':p.stock<=3?`Only ${p.stock} left`:'In stock'}
function card(p){return `<article class="product-card"><div class="product-stage"><span class="stock ${p.stock===0?'out':p.stock<=3?'low':''}">${stockLabel(p)}</span><button class="save-heart ${wishlist.includes(p.id)?'saved':''}" data-wish="${p.id}" aria-label="Save ${esc(p.name)} to wishlist" aria-pressed="${wishlist.includes(p.id)}">${wishlist.includes(p.id)?'♥':'♡'}</button><button class="product-open" data-product="${p.id}" aria-label="View ${esc(p.name)}"><img src="${esc(p.images[0])}" alt="${esc(p.name)}${p.illustrative?' — illustrative artwork':''}" width="300" height="350" loading="lazy"></button><button class="quick" data-quick="${p.id}" aria-label="Add ${esc(p.name)} to bag" ${p.stock===0?'disabled':''}>+</button></div><div class="product-meta"><div class="eyebrow">${esc(p.brand)} · ${esc(p.category)}</div><button class="product-title" data-product="${p.id}">${esc(p.name)}</button><span class="product-price">${money(p.price)}</span><small>${esc(p.sizes.join(' / '))}</small></div></article>`}
function home(){const featured=state.products.filter(p=>p.featured).slice(0,4);const title=state.settings.heroTitle;return `<section class="hero restored-hero ${state.settings.heroVideo?'has-video':''}" id="home">${state.settings.heroVideo?`<video id="hero-video" src="${esc(state.settings.heroVideo)}" muted loop playsinline ${reduced?'':'autoplay'}></video><button class="video-toggle" data-action="video">${reduced?'Play':'Pause'} background video</button>`:''}<div class="hero-layout wrap"><div class="hero-copy"><div class="eyebrow">The small-batch beauty edit</div><h1>${title==='A little rare. A little royal.'?'A little rare.<br>A little <em>royal.</em><br>Entirely you.':esc(title)}</h1><p class="hero-description">${esc(state.settings.heroSubtitle==='Imported makeup, thoughtful skincare and unforgettable scents. A fresh edit, in beautifully small quantities.'?'Coveted makeup, beautiful skincare, unforgettable scents. Sourced abroad. Curated in small quantities. Yours to discover.':state.settings.heroSubtitle)}</p><div class="actions"><a class="btn" href="./index.html?page=shop">Shop this month’s arrivals <span>↗</span></a><a class="text-link" data-whatsapp href="${wa()}" target="_blank" rel="noopener">Message us on WhatsApp ↗</a></div><div class="hero-foot"><span>Imported finds</span><span>Small quantities</span><span>Personal service</span></div></div><div class="hero-art" aria-label="Floating perfume and lipstick artwork"><div class="arch"></div><div class="halo"></div><div class="plinth"></div><img class="hero-product" id="hero-perfume" src="./assets/hero-perfume.svg" fetchpriority="high" alt="Illustrated rose perfume bottle"><img class="hero-product second" id="hero-lipstick" src="./assets/hero-lipstick.svg" fetchpriority="high" alt="Illustrated burgundy lipstick"><div class="orbit-note">THE CURATED<b>beauty</b>COLLECTION</div><div class="floating-tag">Find your next<strong>little obsession.</strong></div><div class="hero-caption">BEAUTY WORTH DISCOVERING — VOL. 01</div></div></div></section><div class="shipment"><b>SMALL SHIPMENTS. SPECIAL FINDS.</b><span class="diamond">✧</span><span>${state.products.length} curated products</span><span class="diamond">✧</span><span>Next restock unconfirmed</span></div><section class="featured-section wrap"><div class="section-heading"><div><div class="eyebrow">A few of our favourites</div><h2>The featured <em>edit.</em></h2></div><a class="text-link" href="./index.html?page=shop">Shop all beauty ↗</a></div><div class="grid">${(featured.length?featured:state.products.slice(0,4)).map(card).join('')}</div><p class="sample-caption">Sample catalogue. Illustrated packshots are marked in product details; confirm shades and availability with our team.</p></section><section class="wrap home-category-section"><div class="category-edit">${state.categories.map(c=>`<a class="category-tile" href="./index.html?page=shop&category=${c.id}"><div><strong>${esc(c.name)}</strong><small>${state.products.filter(p=>p.category_id===c.id).length} BEAUTY FINDS</small></div><span>↗</span></a>`).join('')}</div></section><section class="editorial" id="story"><div class="editorial-picture"><img src="./assets/campaign.png" loading="lazy" alt="Decorative beauty campaign still life"></div><div class="editorial-copy"><div class="eyebrow">A note from The Royal Blush</div><h2>Some things are<br>better in <em>small batches.</em></h2><p>We believe the best beauty finds feel personal. Our collection brings together imported makeup, skincare and fragrance in small, considered quantities.</p><p>Every shipment is a new edit. A little discovery. A little delight. Something that feels entirely you.</p><a class="text-link" href="./index.html?page=shop">Find your next little obsession ↗</a></div></section><section class="faq-section wrap"><div><div class="eyebrow">Here to make it simple</div><h2>Before you<br><em>fall in love.</em></h2><p>A little guidance for your next beauty find.</p></div><div>${faq()}</div></section>`}
function faq(){return `<details><summary>How do I place an order?</summary><p>Add your favourite products to your bag, enter your delivery details, then send the prepared enquiry on WhatsApp. Our team confirms availability, delivery and payment before the order is final.</p></details><details><summary>Will sold-out products return?</summary><p>Our shipments are small and the selection can change. Message us about a favourite; we will confirm whether another shipment is expected.</p></details><details><summary>Can you help me choose a shade?</summary><p>Of course. Use the website chat to speak with the store team, or send us the product name on WhatsApp.</p></details><details><summary>What are your delivery options?</summary><p>${esc(state.settings.delivery)}</p></details>`}
function shop(wish=false){return `<section class="wrap collection-page"><div class="page-title"><div class="breadcrumbs"><a href="./index.html">Home</a> / ${wish?'Wishlist':'The collection'}</div><h1>${wish?'Your little favourites.':'The beauty collection.'}</h1><p>${wish?'The finds you have your eye on, all in one place.':'Discover your next everyday essential or something a little extraordinary.'}</p></div><div class="shop-controls"><label class="search"><span aria-hidden="true">⌕</span><input id="shop-search" type="search" aria-label="Search products" placeholder="Search products or brands…" value="${esc(search)}"></label><select id="shop-sort" class="sort-select" aria-label="Sort products"><option value="featured">Featured first</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="new">Newest first</option><option value="name">Name: A–Z</option></select></div><div class="toolbar"><div class="filters" role="group" aria-label="Product categories"><button class="filter ${filter==='All'?'active':''}" data-filter="All" aria-pressed="${filter==='All'}">All finds</button>${state.categories.map(c=>`<button class="filter ${filter===String(c.id)?'active':''}" data-filter="${c.id}" aria-pressed="${filter===String(c.id)}">${esc(c.name)}</button>`).join('')}</div><span class="result-count" id="result-count"></span></div><div id="shop-grid" class="grid"></div><p class="sample-caption">Prices are in PKR. Final availability and delivery charges are confirmed by our team.</p></section>`}
function renderShopGrid(){if(!$('#shop-grid'))return;let products=state.products.filter(p=>(route!=='/wishlist'||wishlist.includes(p.id))&&(filter==='All'||String(p.category_id)===filter)&&(p.name+' '+p.brand+' '+p.category).toLowerCase().includes(search.toLowerCase()));products.sort(sort==='price-low'?(a,b)=>a.price-b.price:sort==='price-high'?(a,b)=>b.price-a.price:sort==='new'?(a,b)=>b.id-a.id:sort==='name'?(a,b)=>a.name.localeCompare(b.name):(a,b)=>Number(b.featured)-Number(a.featured));$('#shop-grid').innerHTML=products.length?products.map(card).join(''):'<div class="wish-empty"><h3>No beauty finds here yet.</h3><p>Try another search or category, or browse the full collection.</p><a class="btn" href="./index.html?page=shop">Explore all products ↗</a></div>';$('#result-count').textContent=products.length+' beautiful finds';tilt()}
function authForm(){return '<section class="account-layout wrap"><div class="account-intro"><div class="eyebrow">Client preview</div><h1>Your beauty<br><em>account.</em></h1><p>Explore a sample customer profile, saved favourites and order enquiries.</p></div><section class="account-form"><h2>Try a sample account</h2><p>This is a design demonstration. No real account is created and no password is needed.</p><form id="auth-form"><p class="error" role="alert"></p><button class="btn full">Enter customer demo ↗</button></form><p class="helper">Please use fictional details only. Changes stay in this browser.</p></section></section>'}

function setup(){return `<section class="account-layout wrap"><div class="account-intro"><div class="eyebrow">The Royal Blush · First run</div><h1>Your store.<br><em>Your workspace.</em></h1><p>Create the owner account once. After that, only your owner login can access products, categories, settings and customer messages.</p><a class="text-link" href="./index.html">View the boutique ↗</a></div><div class="account-form"><h2>Set up the owner account</h2><p class="setup-note">Open <strong>data/setup-key.txt</strong> in this project’s VS Code folder and paste its setup key below. This file is generated when you run <code>npm start</code>. It is deleted after setup.</p><form id="setup-form"><label class="form-field">Setup key<input name="key" required type="password" autocomplete="off"></label><label class="form-field">Your name<input name="name" required maxlength="80" autocomplete="name"></label><label class="form-field">Owner email<input name="email" required type="email" autocomplete="email"></label><label class="form-field">Create password<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><p class="form-hint">Use at least 10 characters. Keep this login for your store team.</p><p class="error" role="alert"></p><button class="btn full">Create owner account ↗</button></form></div></section>`}
function profile(){const u=state.user;return `<section class="wrap"><div class="page-title"><div class="eyebrow">Your Royal Blush account</div><h1>Hello, ${esc(u.name.split(' ')[0])}.</h1><div class="inline-actions"><a class="text-link" href="./index.html?page=wishlist">My wishlist ↗</a>${u.role==='admin'?'<a class="text-link" href="./index.html?page=admin">Owner workspace ↗</a>':''}<button class="text-link" data-action="logout">Sign out</button></div></div><div class="profile-grid"><section class="panel"><h2>Your details</h2><form id="profile-form"><label class="form-field">Name<input name="name" value="${esc(u.name)}" required maxlength="80" autocomplete="name"></label><label class="form-field">Email<input value="${esc(u.email)}" disabled></label><label class="form-field">Phone<input name="phone" value="${esc(u.phone)}" maxlength="40" autocomplete="tel"></label><label class="form-field">Delivery address<textarea name="address" maxlength="500" autocomplete="street-address">${esc(u.address)}</textarea></label><p class="error" role="alert"></p><button class="btn">Save details ↗</button></form></section><section class="panel"><h2>Change password</h2><form id="password-form"><label class="form-field">Current password<input name="current" type="password" required maxlength="128" autocomplete="current-password"></label><label class="form-field">New password<input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></label><p class="form-hint">Password changes are unavailable in this sample. Do not enter a real password.</p><p class="error" role="alert"></p><button class="btn secondary" disabled>Demo only</button></form></section><section class="panel wide"><h2>Your order enquiries</h2><p class="helper">These are requests sent to the store. Payment and final order confirmation happen with our team.</p><div id="account-enquiries">Loading your enquiries…</div></section></div></section>`}
function info(){return `<section class="info-page wrap"><div class="page-title"><div class="eyebrow">A little help, whenever you need it</div><h1>Customer care.</h1></div>${[['Delivery',state.settings.delivery],['Payment',state.settings.payment],['Returns & product concerns',state.settings.returns]].map(([title,text])=>`<section class="panel"><h2>${title}</h2><p>${esc(text)}</p></section>`).join('')}<div class="panel"><h2>Frequently asked questions</h2>${faq()}</div><p class="helper">Client preview only. All changes stay in this browser. Do not enter real customer details or payment information.</p><button class="btn" data-action="chat">Talk to our team ↗</button></section>`}
function render(){const admin=route==='/admin'||route==='/setup';if(admin){document.title='Owner workspace — The Royal Blush';if(state.setupRequired){$('#app').innerHTML=setup();return}if(!state.user){signup=false;$('#app').innerHTML=authForm(true);return}if(state.user.role!=='admin'){$('#app').innerHTML=`<div class="account-layout wrap"><div class="panel"><h2>Owner access required</h2><p>You are signed in as a customer. Sign out to use the owner account.</p><button class="btn" data-action="logout">Sign out</button> <a class="text-link" href="./index.html">Back to store</a></div></div>`;return}renderAdmin();return}const content=route==='/shop'||route==='/wishlist'?shop(route==='/wishlist'):route==='/account'?(state.user?profile():authForm()):route==='/info'?info():home();$('#app').innerHTML=header()+`<main id="main" class="site-main">${content}</main>`+footer()+floating();updateCounts();renderShopGrid();tilt();if(route==='/account'&&state.user)loadEnquiries();if(state.settings.heroVideo&&$('#hero-video')){$('#hero-video').addEventListener('error',()=>{$('#hero-video').hidden=true;$('.video-toggle').hidden=true;$('.restored-hero').classList.remove('has-video');toast('The background video could not play; the floating 3D hero is shown instead.')})}}
function tilt(){if(reduced||!matchMedia('(hover:hover) and (pointer:fine)').matches)return;$$('.product-stage').forEach(el=>{el.onpointermove=e=>{const r=el.getBoundingClientRect();el.style.transform=`rotateX(${-(e.clientY-r.top-r.height/2)/40}deg) rotateY(${(e.clientX-r.left-r.width/2)/35}deg) translateY(-4px)`};el.onpointerleave=()=>el.style.transform=''})}
function dialog(content,{id='modal',className='',title='Dialog'}={}){const old=$('#'+id);if(old)old.remove();const d=document.createElement('dialog');d.id=id;d.className=className;d.setAttribute('aria-label',title);d.innerHTML=content;$('#dialogs').append(d);d.addEventListener('close',()=>{d.remove();if(!$$('dialog[open]').length)document.body.classList.remove('locked')});d.showModal();document.body.classList.add('locked');return d}
function dialogTop(title){return `<div class="dialog-top"><h2>${title}</h2><button class="close" data-action="close-dialog" aria-label="Close dialog">×</button></div>`}
function showProduct(id){const p=findProduct(id);if(!p)return;selectedProduct=p.id;quantity=1;galleryIndex=0;selectedShade=p.shades[0]||'';selectedSize=p.sizes[0]||'';dialog(dialogTop('The beauty edit')+'<div id="detail-content"></div>',{id:'product-modal',className:'product-dialog',title:p.name});renderDetail()}
function renderDetail(){const p=findProduct(selectedProduct);if(!p)return;$('#detail-content').innerHTML=`<div class="detail-layout"><div><div class="detail-image-wrap"><img class="detail-image" id="detail-image" src="${esc(p.images[galleryIndex])}" alt="${esc(p.name)}" tabindex="0" role="button" aria-label="Toggle image zoom"><span class="zoom-note">Click or tap image to zoom</span></div><div class="gallery-thumbs">${p.images.map((src,i)=>`<button class="gallery-thumb ${i===galleryIndex?'active':''}" data-gallery="${i}" aria-label="View image ${i+1}"><img src="${esc(src)}" alt="Product image ${i+1}"></button>`).join('')}</div></div><div class="detail-copy"><div class="eyebrow">${esc(p.brand)} · ${esc(p.category)}</div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p>${p.illustrative?'<p class="small-note">Illustrative packshot. Ask our team for actual product photos and shade confirmation.</p>':''}<div class="price">${money(p.price)}</div><div class="availability">${stockLabel(p)}</div>${p.shades.length?`<label class="option-label">Shade<select id="detail-shade">${p.shades.map(v=>`<option ${selectedShade===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`:''}${p.sizes.length?`<label class="option-label">Size<select id="detail-size">${p.sizes.map(v=>`<option ${selectedSize===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`:''}<div class="quantity"><button data-detail-qty="-1" aria-label="Decrease quantity" ${quantity<=1?'disabled':''}>−</button><output>${quantity}</output><button data-detail-qty="1" aria-label="Increase quantity" ${quantity>=p.stock?'disabled':''}>+</button></div><button class="btn" data-action="detail-add" ${p.stock?'':'disabled'}>${p.stock?'Add to beauty bag':'Currently sold out'} +</button><a class="btn secondary" href="${wa(`Hello! Please tell me about ${p.name} (${p.brand}), listed at ${money(p.price)}.`)}" target="_blank" rel="noopener">Ask on WhatsApp ↗</a>${p.video?`<a class="text-link" href="${esc(p.video)}" target="_blank" rel="noopener noreferrer">Watch product video ↗</a>`:''}</div></div>`}
function addToBag(productId,q=1,shade='',size=''){const p=findProduct(productId);if(!p)return;const inBag=cart.filter(i=>i.productId===p.id).reduce((n,i)=>n+i.quantity,0);if(inBag+q>p.stock){toast(p.stock?'That is all the available stock for this product.':'This find is sold out.');return}const item={productId:p.id,quantity:q,shade:shade||p.shades[0]||'',size:size||p.sizes[0]||''};const existing=cart.find(i=>itemKey(i)===itemKey(item));if(existing)existing.quantity+=q;else cart.push(item);persist();toast(p.name+' added to your bag.');const button=$('[data-action="bag"]');button?.classList.remove('bump');if(button){void button.offsetWidth;button.classList.add('bump')}}
function showBag(){dialog(dialogTop('Your beauty bag')+'<div id="bag-content"></div>',{id:'bag-modal',className:'bag-dialog',title:'Shopping bag'});renderBag()}
function renderBag(){cart=normalizeCart(cart);updateCounts();if(!cart.length){$('#bag-content').innerHTML='<div class="empty"><h3>A little room for beauty.</h3><p>Your bag is waiting for its first lovely find.</p><a class="btn" href="./index.html?page=shop">Explore the collection ↗</a></div>';return}let total=0;$('#bag-content').innerHTML=cart.map((item,i)=>{const p=findProduct(item.productId);total+=item.quantity*p.price;return `<div class="bag-line"><img src="${esc(p.images[0])}" alt="${esc(p.name)}"><div><h3>${esc(p.name)}</h3><div class="variant-label">${esc([item.shade,item.size].filter(Boolean).join(' · '))}</div><span class="product-price">${money(p.price*item.quantity)}</span><div class="line-bottom"><div class="quantity"><button data-cart-index="${i}" data-delta="-1" aria-label="Decrease quantity">−</button><output>${item.quantity}</output><button data-cart-index="${i}" data-delta="1" aria-label="Increase quantity">+</button></div><button class="remove" data-remove-cart="${i}">Remove</button></div></div></div>`}).join('')+`<div class="bag-total"><span>Subtotal</span><strong>${money(total)}</strong></div><p class="bag-note">Delivery, stock and payment will be confirmed by our team. Your bag does not reserve products.</p><button class="btn checkout" data-action="checkout">Continue to order enquiry ↗</button>`}
function checkout(){dialog(dialogTop('Your order enquiry')+`<p class="helper">Preview an order enquiry using fictional details. No order, payment or message is sent.</p><form id="checkout-form"><label class="form-field">Full name<input name="name" value="${esc(state.user?.name||'')}" required maxlength="80" autocomplete="name"></label><label class="form-field">Phone / WhatsApp<input name="phone" value="${esc(state.user?.phone||'')}" required maxlength="40" autocomplete="tel"></label><label class="form-field">Delivery address<textarea name="address" required maxlength="500" autocomplete="street-address">${esc(state.user?.address||'')}</textarea></label><p class="error" role="alert"></p><button class="btn full">Prepare WhatsApp enquiry ↗</button></form>`,{id:'checkout-modal',className:'small-dialog',title:'Order enquiry'})}
async function afterLogin(){const guestCart=readLocal('rb-demo-cart',[]),guestWish=readLocal('rb-demo-wishlist',[]);state=await api('/bootstrap');cart=normalizeCart([...state.preferences.cart,...guestCart]);wishlist=[...new Set([...state.preferences.wishlist,...guestWish])].filter(id=>findProduct(id));await api('/preferences','PUT',{cart,wishlist});writeLocal('rb-demo-cart',[]);writeLocal('rb-demo-wishlist',[]);location.href=demoURL(route==='/admin'||route==='/setup'?'/admin':'/account')}
async function loadEnquiries(){try{const r=await api('/enquiries');if($('#account-enquiries'))$('#account-enquiries').innerHTML=r.enquiries.length?r.enquiries.map(e=>`<div class="enquiry-card"><strong>Enquiry #${e.id} · ${money(e.total)}</strong> <span class="status-pill">${esc(e.status)}</span><p>${esc(date(e.created))}</p><p>${e.items.map(i=>`${esc(i.name)} × ${i.quantity}`).join(' · ')}</p></div>`).join(''):'<p class="helper">No enquiries yet. Your next beauty find is waiting in the collection.</p>'}catch(e){if($('#account-enquiries'))$('#account-enquiries').textContent=e.message}}
/* Customer chat: messages are stored on the server. No canned bot replies. */
function chatBody(){if(customerConversation)return '<div class="chat-messages" id="customer-messages" role="log" aria-live="polite"></div><div class="chat-status" id="customer-chat-status"></div><form class="chat-form" id="customer-chat-form"><input name="body" aria-label="Your message" placeholder="Write to our team…" maxlength="2000" required><button>Send ↗</button></form>';return `<div class="chat-intro"><p>Try a sample conversation. Messages stay in this browser; the real store does not receive them.</p><form id="start-chat-form">${state.user?'':`<label class="form-field">Your name<input name="name" maxlength="80" required autocomplete="name"></label>`}<p class="error" role="alert"></p><button class="btn full">Start a conversation ↗</button></form>${state.user?'':'<p class="form-hint">Guest chat stays linked to this browser. <a class="text-link" href="./index.html?page=account">Sign in</a> to explore the sample customer profile.</p>'}</div>`}
async function openChat(){chatOpened=true;$('#chat-panel').hidden=false;$$('[data-action="chat"]').forEach(b=>b.setAttribute('aria-expanded','true'));await pollCustomer();$('#chat-inner').innerHTML=chatBody();customerFingerprint='';await pollCustomer();$('#customer-chat-form input')?.focus()}
function messageHTML(messages){return messages.map(m=>`<div class="chat-message ${m.sender}">${esc(m.body)}<time>${m.sender==='admin'?'Royal Blush · ':''}${esc(date(m.created))}</time></div>`).join('')}
function updateMessages(target,messages,fingerprintName){const el=$(target);if(!el)return;const fp=JSON.stringify(messages.map(m=>[m.id,m.body]));if(fingerprintName==='customer'?fp===customerFingerprint:fp===messageFingerprint)return;const wasNearBottom=el.scrollHeight-el.scrollTop-el.clientHeight<70;if(fingerprintName==='customer')customerFingerprint=fp;else messageFingerprint=fp;el.innerHTML=messages.length?messageHTML(messages):'<p class="helper">Your conversation starts here. Our team will reply as soon as they can.</p>';if(wasNearBottom||messages.length<3)el.scrollTop=el.scrollHeight}
async function pollCustomer(){if(route==='/admin'||route==='/setup')return;const r=await api('/chat');if(!customerConversation&&r.conversations.length)customerConversation=r.conversations[0].id;const badge=$('#chat-unread');if(badge){badge.hidden=!r.unread;badge.textContent=r.unread}if(chatOpened&&customerConversation){if(!$('#customer-messages')){$('#chat-inner').innerHTML=chatBody();customerFingerprint=''}const data=await api(`/chat/${customerConversation}/messages`);updateMessages('#customer-messages',data.messages,'customer');if(!document.hidden)await api(`/chat/${customerConversation}/read`,'POST',{});if($('#customer-chat-status'))$('#customer-chat-status').textContent='Local demo messages · not sent to the store'}}
/* Owner workspace */
const adminTitles={overview:'Overview',products:'Products',categories:'Categories',messages:'Customer messages',enquiries:'Order enquiries',settings:'Store settings'};
function renderAdmin(){if(!adminTitles[adminTab])adminTab='overview';$('#app').innerHTML=`<div class="admin-shell"><aside class="admin-sidebar">${logo()}<div class="workspace-label">OWNER WORKSPACE</div><nav class="admin-nav" aria-label="Owner dashboard">${Object.entries(adminTitles).map(([key,label],i)=>`<button data-admin-tab="${key}" class="${adminTab===key?'active':''}" ${adminTab===key?'aria-current="page"':''}><span aria-hidden="true">${['◈','◇','▦','☏','☷','⚙'][i]}</span>${label}${key==='messages'?'<span class="nav-badge" id="admin-unread" hidden></span>':''}</button>`).join('')}</nav><div class="admin-sidebar-bottom"><a href="./index.html" target="_blank" rel="noopener">View storefront ↗</a><a href="./index.html?page=account">My account & password</a><button data-action="logout">Sign out</button></div></aside><main class="admin-main" id="main"><div class="admin-topbar"><div><div class="eyebrow">THE ROYAL BLUSH / WORKSPACE</div><h1 id="admin-page-title">${adminTitles[adminTab]}</h1></div><div class="owner-chip"><span class="owner-avatar">${esc(state.user.name.slice(0,1).toUpperCase())}</span>${esc(state.user.name)}</div></div><div id="admin-content"></div></main></div>`;renderAdminSection()}
function renderAdminSection(){if(!$('#admin-content'))return;$$('[data-admin-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.adminTab===adminTab);if(b.dataset.adminTab===adminTab)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});$('#admin-page-title').textContent=adminTitles[adminTab];$('#admin-content').innerHTML=adminTab==='overview'?overviewPage():adminTab==='products'?productsPage():adminTab==='categories'?categoriesPage():adminTab==='messages'?inboxPage():adminTab==='enquiries'?enquiriesPage():settingsPage();if(adminTab==='products')adminProductRows();if(adminTab==='messages'){renderConversationList();if(activeConversation)selectConversation(activeConversation)}updateAdminBadge()}
async function loadOverview(){overview=await api('/admin/overview');updateAdminBadge();if(adminTab==='overview'&&$('#admin-content'))$('#admin-content').innerHTML=overviewPage();if(adminTab==='messages'){renderConversationList();if(activeConversation)await pollAdminMessages()}}
function updateAdminBadge(){const badge=$('#admin-unread');if(badge&&overview){badge.hidden=!overview.stats.unread;badge.textContent=overview.stats.unread}}
function overviewPage(){if(!overview)return '<div class="panel">Loading your workspace…</div>';const stats=overview.stats;return `<div class="dashboard-stats">${[['Products',stats.products,'In your collection'],['Low stock',stats.lowStock,'3 pieces or fewer'],['Customers',stats.customers,'Registered accounts'],['Unread messages',stats.unread,'Waiting for your reply']].map(([label,n,sub])=>`<div class="metric"><span>${label}</span><strong>${n}</strong><small>${sub}</small></div>`).join('')}</div><div class="admin-columns"><section class="panel"><div class="admin-section-title"><h2>Your collection</h2><button class="text-link" data-admin-tab="products">Manage ↗</button></div>${state.products.filter(p=>p.stock<=3).slice(0,5).map(p=>`<div class="category-row"><div><h3>${esc(p.name)}</h3><p>${esc(p.category)} · ${money(p.price)}</p></div><span class="status-pill">${stockLabel(p)}</span></div>`).join('')||'<p class="helper">All products have healthy stock levels.</p>'}</section><section class="panel"><div class="admin-section-title"><h2>Recent conversations</h2><button class="text-link" data-admin-tab="messages">Open inbox ↗</button></div>${overview.conversations.slice(0,5).map(c=>`<button class="conversation" data-open-conversation="${c.id}"><strong>${esc(c.name)} ${c.unread?`<span class="nav-badge">${c.unread}</span>`:''}</strong><p>${esc(c.last_message||'No messages yet')}</p><small>${esc(date(c.updated))}</small></button>`).join('')||'<p class="helper">Customer messages will appear here. Replies are sent from your inbox.</p>'}<div class="pending-note" style="margin-top:20px">${stats.enquiries} order enquiries received. Enquiries are not paid orders; confirm each request with the customer.</div></section></div>`}
function productsPage(){return `<div class="admin-toolbar"><label class="search"><span>⌕</span><input id="admin-search" type="search" aria-label="Search catalogue" placeholder="Search your products…" value="${esc(adminSearch)}"></label><button class="btn" data-action="new-product">+ Add product</button></div><section class="panel"><div class="table-wrap"><table class="admin-table"><thead><tr><th>Product</th><th>Name / brand</th><th>Category</th><th>Price</th><th>Stock</th><th>Actions</th></tr></thead><tbody id="admin-product-rows"></tbody></table></div></section>`}
function adminProductRows(){if(!$('#admin-product-rows'))return;const list=state.products.filter(p=>(p.name+' '+p.brand+' '+p.category).toLowerCase().includes(adminSearch.toLowerCase()));$('#admin-product-rows').innerHTML=list.map(p=>`<tr><td><img src="${esc(p.images[0])}" alt="${esc(p.name)}"></td><td class="admin-product-name"><strong>${esc(p.name)}</strong><small>${esc(p.brand)}${p.featured?' · Featured':''}</small></td><td>${esc(p.category)}</td><td>${money(p.price)}</td><td><span class="status-pill">${p.stock} units</span></td><td><div class="row-actions"><button class="button-small" data-edit-product="${p.id}">Edit</button><button class="danger-btn" data-delete-product="${p.id}">Delete</button></div></td></tr>`).join('')||'<tr><td colspan="6">No matching products.</td></tr>'}
function categoriesPage(){return `<div class="admin-section-title"><div><h2>Your categories</h2><p class="helper">Create your own categories. They appear in the storefront filters automatically.</p></div></div><section class="panel"><form id="category-add-form" class="inline-actions"><label class="form-field" style="flex:1;margin:0">New category name<input name="name" required maxlength="60" placeholder="e.g. Haircare, Tools, Gift sets"></label><button class="btn" style="align-self:end">+ Add category</button><p class="error" role="alert"></p></form>${state.categories.map(c=>{const count=state.products.filter(p=>p.category_id===c.id).length;return `<div class="category-row"><div><h3>${esc(c.name)}</h3><p>${count} ${count===1?'product':'products'} in this category</p></div><div class="edit-actions"><button class="button-small" data-edit-category="${c.id}">Rename</button><button class="danger-btn" data-delete-category="${c.id}">Delete</button></div></div>`}).join('')}</section>`}
function editCategory(cid){const c=state.categories.find(c=>c.id===cid);dialog(dialogTop('Rename category')+`<form id="category-edit-form" data-id="${cid}"><label class="form-field">Category name<input name="name" value="${esc(c.name)}" required maxlength="60"></label><p class="error" role="alert"></p><button class="btn full">Save category</button></form>`,{className:'small-dialog',title:'Rename category'})}
function deleteCategory(cid){const c=state.categories.find(c=>c.id===cid),count=state.products.filter(p=>p.category_id===cid).length,others=state.categories.filter(c=>c.id!==cid);dialog(dialogTop('Delete category')+`<p>Delete <strong>${esc(c.name)}</strong>?</p><p class="helper">${count?`${count} products must be moved to another category. Their photos and details will be kept.`:'This category has no products.'}</p><form id="category-delete-form" data-id="${cid}">${count?`<label class="form-field">Move products to<select name="moveTo" required><option value="">Choose another category</option>${others.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label>${!others.length?'<p class="error">Create another category first.</p>':''}`:''}<p class="error" role="alert"></p><button class="danger-btn" ${count&&!others.length?'disabled':''}>Delete category${count?' & move products':''}</button></form>`,{className:'small-dialog',title:'Delete category'})}
function productEditor(pid=null){if(!state.categories.length){toast('Add a category before creating a product.');adminTab='categories';renderAdminSection();return}const p=pid?findProduct(pid):null;editingProduct=pid;editImages=p?[...p.images]:[];dialog(dialogTop(p?'Edit beauty find':'Add a beauty find')+`<form id="product-edit-form"><div class="two-fields"><label class="form-field">Product name<input name="name" required maxlength="120" value="${esc(p?.name||'')}"></label><label class="form-field">Brand<input name="brand" required maxlength="80" value="${esc(p?.brand||'')}"></label></div><div class="two-fields"><label class="form-field">Category<select name="category_id">${state.categories.map(c=>`<option value="${c.id}" ${p?.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label class="form-field">Price (PKR)<input name="price" type="number" min="1" max="1000000" step="1" required value="${p?.price||''}"></label></div><div class="two-fields"><label class="form-field">Stock quantity<input name="stock" type="number" min="0" max="10000" step="1" required value="${p?.stock??1}"></label><label class="form-field">Sizes (comma separated)<input name="sizes" maxlength="1000" value="${esc(p?.sizes.join(', ')||'')}" placeholder="30 ml, 50 ml"></label></div><label class="form-field">Shades (comma separated)<input name="shades" maxlength="1000" value="${esc(p?.shades.join(', ')||'')}" placeholder="Rose, Nude, Berry"></label><p class="form-hint">Stock is shared across the selected shades and sizes. Enter the total available pieces.</p><label class="form-field">Description<textarea name="description" maxlength="3000">${esc(p?.description||'')}</textarea></label><label class="form-field">Product photos (up to 6)<input type="file" id="product-photos" accept="image/png,image/jpeg,image/webp" multiple></label><div id="image-editor" class="image-editor"></div><p class="form-hint">First photo is the cover. PNG/JPEG/WebP, up to 5 MB each. Demo uploads stay in this browser; use images below 750 KB.</p><label class="form-field">Product video link (optional)<input name="video" type="url" value="${esc(p?.video||'')}" placeholder="https://…"></label><label class="check-field"><input type="checkbox" name="featured" ${p?.featured?'checked':''}>Feature on homepage</label><label class="check-field"><input type="checkbox" name="illustrative" ${p?.illustrative?'checked':''}>Images are illustrative, not actual product photos</label><p class="error" role="alert"></p><div class="product-editor-footer"><button type="button" class="btn secondary" data-action="close-dialog">Cancel</button><button class="btn" id="save-product">Save product ↗</button></div></form>`,{id:'product-editor',className:'product-editor',title:'Product editor'});renderImageEditor()}
function renderImageEditor(){$('#image-editor').innerHTML=editImages.map((url,i)=>`<div class="image-editor-item"><img src="${esc(url)}" alt="Product photo ${i+1}"><button type="button" data-remove-image="${i}" aria-label="Remove photo ${i+1}">×</button></div>`).join('')}
async function upload(file){if(!file)throw Error('Choose a file first.');const video=file.type.startsWith('video/');if(file.size>(video?50:5)*1024*1024)throw Error(video?'Video must be under 50 MB.':'Photo must be under 5 MB.');const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('Could not read this file.'));reader.readAsDataURL(file)});return(await api('/admin/upload','POST',{mime:file.type,data:base64})).url}
function inboxPage(){return `<div class="inbox"><aside class="inbox-list"><div class="inbox-list-header"><span class="connection-dot"></span>Customer conversations</div><div id="conversation-list"></div></aside><section class="inbox-thread"><div class="inbox-title" id="inbox-title">Select a conversation</div><div class="chat-messages admin-view" id="admin-messages" role="log" aria-live="polite"><div class="admin-empty"><h3>A personal touch.</h3><p>Select a customer to read their messages and reply.</p></div></div><div class="inbox-notice" id="inbox-notice"></div><form class="chat-form" id="admin-chat-form" hidden><input name="body" placeholder="Write your reply…" aria-label="Reply to customer" maxlength="2000" required><button>Send reply ↗</button></form></section></div>`}
function renderConversationList(){if(!$('#conversation-list')||!overview)return;const html=overview.conversations.map(c=>`<button class="conversation ${activeConversation===c.id?'active':''}" data-conversation="${c.id}"><strong>${esc(c.name)}${c.unread?`<span class="nav-badge">${c.unread}</span>`:''}</strong><p>${esc(c.last_message||'Conversation started')}</p><small>${esc(c.email||'Guest customer')} · ${esc(date(c.updated))}</small></button>`).join('')||'<div class="admin-empty">No conversations yet. Customer chats appear here automatically.</div>';if($('#conversation-list').innerHTML!==html)$('#conversation-list').innerHTML=html}
async function selectConversation(id){activeConversation=Number(id);messageFingerprint='';const c=overview?.conversations.find(c=>c.id===activeConversation);if($('#inbox-title'))$('#inbox-title').textContent=c?c.name+' · '+(c.email||'Guest customer'):'Customer conversation';if($('#admin-chat-form'))$('#admin-chat-form').hidden=false;renderConversationList();await pollAdminMessages();$('#admin-chat-form input')?.focus()}
async function pollAdminMessages(){if(!activeConversation||!$('#admin-messages'))return;const cid=activeConversation,r=await api(`/chat/${cid}/messages`);if(cid!==activeConversation)return;updateMessages('#admin-messages',r.messages,'admin');if(!document.hidden)await api(`/chat/${cid}/read`,'POST',{});if($('#inbox-notice'))$('#inbox-notice').textContent='Demo messages · shared only within this browser'}
function enquiriesPage(){return `<section class="panel"><div class="admin-section-title"><h2>Customer requests</h2></div><p class="helper">These are product enquiries, not paid orders. Confirm stock, payment and delivery directly with the customer. Status updates do not deduct stock; adjust quantities in Products after a confirmed sale.</p>${overview?.enquiries.length?overview.enquiries.map(e=>`<div class="enquiry-card"><div class="inline-actions"><strong>#${e.id} · ${esc(e.name)} · ${money(e.total)}</strong><select class="sort-select" data-enquiry-status="${e.id}" aria-label="Enquiry ${e.id} status">${['New','Contacted','Closed'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></div><p>${esc(e.phone)} · ${esc(date(e.created))}</p><p>${esc(e.address)}</p><div class="request-items">${e.items.map(i=>`${esc(i.name)} ${esc([i.shade,i.size].filter(Boolean).join(' / '))} × ${i.quantity} — ${money(i.price*i.quantity)}`).join('<br>')}</div></div>`).join(''):'<div class="admin-empty">No order enquiries yet.</div>'}</section>`}
function settingsPage(){const s=state.settings;return `<section class="panel settings-form"><h2>Storefront details</h2><form id="settings-form"><label class="form-field">Hero headline<input name="heroTitle" required maxlength="120" value="${esc(s.heroTitle)}"></label><label class="form-field">Hero description<textarea name="heroSubtitle" maxlength="3000">${esc(s.heroSubtitle)}</textarea></label><label class="form-field">WhatsApp number (country code, digits only)<input name="whatsapp" required pattern="[0-9]{8,15}" value="${esc(s.whatsapp)}"></label><h2>Customer information</h2>${['delivery','payment','returns'].map(key=>`<label class="form-field">${key[0].toUpperCase()+key.slice(1)}<textarea name="${key}" maxlength="3000">${esc(s[key])}</textarea></label>`).join('')}<p class="error" role="alert"></p><button class="btn">Save store settings ↗</button></form><h2>Homepage background</h2>${s.heroVideo?`<video class="video-preview" src="${esc(s.heroVideo)}" controls muted></video>`:'<img class="settings-image" src="./assets/hero-perfume.svg" alt="Current floating 3D hero artwork">'}<label class="form-field">Upload a background video<input id="hero-upload" disabled type="file" accept="video/mp4,video/webm"></label><p class="form-hint">MP4 or WebM, up to 50 MB. Video upload is available in the full server version; disabled in this static preview.</p><div id="video-upload-status" class="helper" role="status"></div>${s.heroVideo?'<button class="danger-btn" data-action="remove-hero-video">Remove video & restore 3D hero</button>':''}</section>`}
function confirmation(title,text,action){dialog(dialogTop(title)+`<p>${text}</p><p class="error" role="alert"></p><div class="inline-actions"><button class="btn secondary" data-action="close-dialog">Cancel</button><button class="danger-btn" id="confirm-action">Confirm delete</button></div>`,{id:'confirm-modal',className:'small-dialog',title});$('#confirm-action').onclick=async e=>{e.target.disabled=true;try{await action();$('#confirm-modal')?.close()}catch(error){$('#confirm-modal .error').textContent=error.message;e.target.disabled=false}}}
async function saveAndRefresh(){await reloadCatalogue();overview=await api('/admin/overview');renderAdminSection();toast('Changes saved. Your storefront is up to date.')}
/* One event layer keeps keyboard and pointer behaviour consistent. */
document.addEventListener('click',async event=>{const el=event.target.closest('button,a');if(!el)return;try{
 if(el.dataset.product){showProduct(Number(el.dataset.product));return}
 if(el.dataset.quick){const p=findProduct(el.dataset.quick);if(p.shades.length>1||p.sizes.length>1)showProduct(p.id);else addToBag(p.id);return}
 if(el.dataset.wish){const id=Number(el.dataset.wish);wishlist=wishlist.includes(id)?wishlist.filter(x=>x!==id):[...wishlist,id];persist();if(route==='/wishlist')renderShopGrid();return}
 if(el.dataset.filter){filter=el.dataset.filter;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter))});renderShopGrid();return}
 if(el.dataset.auth){signup=el.dataset.auth==='signup';render();return}
 if(el.dataset.gallery!==undefined){galleryIndex=Number(el.dataset.gallery);renderDetail();return}
 if(el.dataset.detailQty){quantity=Math.max(1,Math.min(findProduct(selectedProduct).stock,quantity+Number(el.dataset.detailQty)));renderDetail();return}
 if(el.dataset.cartIndex!==undefined){const i=Number(el.dataset.cartIndex),item=cart[i],delta=Number(el.dataset.delta);if(delta>0){const stock=findProduct(item.productId).stock,total=cart.filter(x=>x.productId===item.productId).reduce((n,x)=>n+x.quantity,0);if(total>=stock){toast('No more stock is available for this product.');return}}item.quantity+=delta;if(!item.quantity)cart.splice(i,1);persist();renderBag();return}
 if(el.dataset.removeCart!==undefined){cart.splice(Number(el.dataset.removeCart),1);persist();renderBag();return}
 if(el.dataset.adminTab){adminTab=el.dataset.adminTab;history.replaceState(null,'','#'+adminTab);renderAdminSection();await loadOverview();return}
 if(el.dataset.editProduct){productEditor(Number(el.dataset.editProduct));return}
 if(el.dataset.deleteProduct){const p=findProduct(el.dataset.deleteProduct);confirmation('Delete product?',`Remove <strong>${esc(p.name)}</strong> from the catalogue? Existing enquiry records will be kept.`,async()=>{await api('/admin/products/'+p.id,'DELETE');await saveAndRefresh()});return}
 if(el.dataset.editCategory){editCategory(Number(el.dataset.editCategory));return}
 if(el.dataset.deleteCategory){deleteCategory(Number(el.dataset.deleteCategory));return}
 if(el.dataset.removeImage!==undefined){editImages.splice(Number(el.dataset.removeImage),1);renderImageEditor();return}
 if(el.dataset.conversation){await selectConversation(Number(el.dataset.conversation));return}
 if(el.dataset.openConversation){activeConversation=Number(el.dataset.openConversation);adminTab='messages';history.replaceState(null,'','#messages');renderAdminSection();return}
 switch(el.dataset.action){
 case 'close-dialog':el.closest('dialog').close();break;
 case 'menu':$('#mobile-nav').hidden=!$('#mobile-nav').hidden;el.setAttribute('aria-expanded',String(!$('#mobile-nav').hidden));break;
 case 'bag':await pendingSave.catch(()=>{});await reloadCatalogue();showBag();break;
 case 'detail-add':addToBag(selectedProduct,quantity,selectedShade,selectedSize);break;
 case 'checkout':checkout();break;
 case 'logout':await pendingSave.catch(()=>{});await api('/logout','POST',{});location.href=demoURL(route==='/admin'?'/admin':'/account');break;
 case 'chat':await openChat();break;
 case 'close-chat':chatOpened=false;$('#chat-panel').hidden=true;$$('[data-action="chat"]').forEach(b=>b.setAttribute('aria-expanded','false'));break;
 case 'new-product':productEditor();break;
 case 'remove-hero-video':await api('/admin/settings','PUT',{heroVideo:''});await saveAndRefresh();break;
 case 'video':{const video=$('#hero-video');if(video.paused){await video.play();el.textContent='Pause background video'}else{video.pause();el.textContent='Play background video'}break}
 }
 }catch(error){toast(error.message)}});
document.addEventListener('click',event=>{if(event.target.id==='detail-image')event.target.classList.toggle('zoomed')});
document.addEventListener('keydown',event=>{if(event.target.id==='detail-image'&&['Enter',' '].includes(event.key)){event.preventDefault();event.target.classList.toggle('zoomed')}});
document.addEventListener('input',event=>{if(event.target.id==='shop-search'){search=event.target.value;renderShopGrid()}if(event.target.id==='admin-search'){adminSearch=event.target.value;adminProductRows()}});
document.addEventListener('change',async event=>{const el=event.target;try{if(el.id==='shop-sort'){sort=el.value;renderShopGrid()}if(el.id==='detail-shade')selectedShade=el.value;if(el.id==='detail-size')selectedSize=el.value;if(el.dataset.enquiryStatus){await api('/admin/enquiries/'+el.dataset.enquiryStatus,'PATCH',{status:el.value});toast('Enquiry status saved.')}if(el.id==='product-photos'){const files=[...el.files];if(editImages.length+files.length>6)throw Error('Use at most 6 photos. Remove an existing photo first.');const button=$('#save-product');button.disabled=true;const error=$('#product-edit-form .error');try{error.textContent='Uploading photos…';for(const file of files){if(!file.type.startsWith('image/'))throw Error('Choose PNG, JPEG or WebP photos.');editImages.push(await upload(file))}renderImageEditor();error.textContent='Photo preview ready. Save to apply it in this browser.'}finally{button.disabled=false;el.value=''}}if(el.id==='hero-upload'){el.disabled=true;$('#video-upload-status').textContent='Uploading video…';try{const url=await upload(el.files[0]);await api('/admin/settings','PUT',{heroVideo:url});await saveAndRefresh()}finally{el.disabled=false}}}catch(error){const target=el.closest('form')?.querySelector('.error')||$('#video-upload-status');if(target)target.textContent=error.message;toast(error.message)}});
document.addEventListener('submit',async event=>{const form=event.target;if(!form.id)return;event.preventDefault();const data=Object.fromEntries(new FormData(form)),button=form.querySelector('button[type=submit],button:not([type])'),error=form.querySelector('.error');if(button?.disabled)return;if(button)button.disabled=true;if(error)error.textContent='';try{switch(form.id){
 case 'setup-form':await api('/setup','POST',data);location.href=demoURL('/admin');break;
 case 'auth-form':await api(signup&&route!=='/admin'?'/signup':'/login','POST',data);await afterLogin();break;
 case 'profile-form':{const r=await api('/profile','PATCH',data);state.user=r.user;toast('Your details are saved.');break}
 case 'password-form':await api('/password','POST',data);form.reset();toast('Password updated. Other sessions have been signed out.');break;
 case 'checkout-form':{const r=await api('/enquiries','POST',{...data,items:cart});$('#checkout-modal').innerHTML=dialogTop('Demo enquiry preview')+`<div class="checkout-success"><h3>Enquiry #${r.id}</h3><p>This enquiry is saved in this browser only. No message has been sent.</p><p><strong>${money(r.total)}</strong> before delivery</p><a class="btn full" href="${esc(r.url)}" target="_blank" rel="noopener">View WhatsApp message preview ↗</a></div><p class="helper">Your bag is kept until you remove its items. This is not a payment or stock reservation.</p>`;break}
 case 'start-chat-form':{const r=await api('/chat','POST',{name:state.user?.name||data.name});customerConversation=r.id;$('#chat-inner').innerHTML=chatBody();customerFingerprint='';await pollCustomer();$('#customer-chat-form input')?.focus();break}
 case 'customer-chat-form':if(!customerConversation)throw Error('Start a conversation first.');await api(`/chat/${customerConversation}/messages`,'POST',{body:data.body});form.reset();customerFingerprint='';await pollCustomer();$('#customer-messages').scrollTop=$('#customer-messages').scrollHeight;break;
 case 'admin-chat-form':if(!activeConversation)throw Error('Select a customer first.');await api(`/chat/${activeConversation}/messages`,'POST',{body:data.body});form.reset();messageFingerprint='';await pollAdminMessages();$('#admin-messages').scrollTop=$('#admin-messages').scrollHeight;await loadOverview();break;
 case 'category-add-form':await api('/admin/categories','POST',{name:data.name});await saveAndRefresh();break;
 case 'category-edit-form':await api('/admin/categories/'+form.dataset.id,'PUT',{name:data.name});form.closest('dialog').close();await saveAndRefresh();break;
 case 'category-delete-form':await api('/admin/categories/'+form.dataset.id,'DELETE',{moveTo:data.moveTo?Number(data.moveTo):null});form.closest('dialog').close();await saveAndRefresh();break;
 case 'product-edit-form':{if(!editImages.length)throw Error('Upload at least one product photo.');const payload={...data,category_id:Number(data.category_id),price:Number(data.price),stock:Number(data.stock),images:editImages,shades:data.shades.split(',').map(v=>v.trim()).filter(Boolean),sizes:data.sizes.split(',').map(v=>v.trim()).filter(Boolean),featured:!!data.featured,illustrative:!!data.illustrative};await api('/admin/products'+(editingProduct?'/'+editingProduct:''),editingProduct?'PUT':'POST',payload);form.closest('dialog').close();await saveAndRefresh();break}
 case 'settings-form':await api('/admin/settings','PUT',data);await reloadCatalogue();toast('Store settings saved.');break;
 }}catch(err){if(error)error.textContent=err.message;else if(form.id==='admin-chat-form'&&$('#inbox-notice'))$('#inbox-notice').textContent=err.message;else if(form.id==='customer-chat-form'&&$('#customer-chat-status'))$('#customer-chat-status').textContent=err.message;toast(err.message)}finally{if(button)button.disabled=false}});
window.addEventListener('hashchange',()=>{if(route==='/admin'&&state.user?.role==='admin'){adminTab=location.hash.slice(1)||'overview';if(!adminTitles[adminTab])adminTab='overview';renderAdminSection()}});
setInterval(async()=>{if(document.hidden||chatBusy)return;chatBusy=true;try{if(route==='/admin'&&state.user?.role==='admin')await loadOverview();else await pollCustomer()}catch(error){if(chatOpened&&$('#customer-chat-status'))$('#customer-chat-status').textContent='Connection interrupted. Retrying…';if(adminTab==='messages'&&$('#inbox-notice'))$('#inbox-notice').textContent='Connection interrupted. Retrying…'}finally{chatBusy=false}},3000);
window.addEventListener('focus',()=>{if(!$$('dialog[open]').length&&['/','/shop','/wishlist'].includes(route))reloadCatalogue().then(()=>{if(route==='/shop'||route==='/wishlist')renderShopGrid()}).catch(()=>{})});
bootstrap().catch(error=>{$('#app').innerHTML=`<div class="account-layout wrap"><section class="panel"><h2>Let’s reconnect.</h2><p>${esc(error.message)}</p><p>Run <code>npm start</code> in the project folder and open the localhost URL. This version uses a real backend and cannot run by double-clicking an HTML file.</p><a class="btn" href="./index.html">Try again</a></section></div>`});
